import { Module } from '@nestjs/common';
import { ClientsModule, Transport } from '@nestjs/microservices';
import { OrdersController } from './orders.controller';

@Module({
  imports: [
    ClientsModule.register([
      {
        name: 'ORDERS_QUEUE',
        transport: Transport.RMQ,
        options: {
          urls: ['amqp://localhost:5672'],
          queue: 'orders_queue',
        },
      },
    ]),
  ],
  controllers: [OrdersController],
})
export class AppModule {}

import { Body, Controller, Inject, Post } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';

@Controller('orders')
export class OrdersController {
  constructor(@Inject('ORDERS_QUEUE') private client: ClientProxy) {}

  @Post()
  create(@Body() order: { item: string }) {
    this.client.emit('order_created', order);
    return { message: `Đã nhận đơn ${order.item}, đang xử lý!` };
  }
}

import { NestFactory } from '@nestjs/core';
import { Transport } from '@nestjs/microservices';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.createMicroservice(AppModule, {
    transport: Transport.RMQ,
    options: {
      urls: ['amqp://localhost:5672'],
      queue: 'orders_queue',
    },
  });
  await app.listen();
}
bootstrap();

import { Controller } from '@nestjs/common';
import { EventPattern } from '@nestjs/microservices';

@Controller()
export class OrdersController {
  @EventPattern('order_created')
  handleOrder(order: { item: string }) {
    console.log(`📦 Đang xử lý đơn: ${order.item}`);
  }
}
